package ru.hollowhorizon.additions.questing.registry;

import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;
import net.minecraft.client.renderer.ShaderInstance;
import net.minecraft.resources.ResourceLocation;

public class ModShaders {
    private static final Map<ResourceLocation, ShaderInstance> PROGRAMS = new LinkedHashMap<ResourceLocation, ShaderInstance>();
    public static final ResourceLocation DEFAULT_BACKGROUND_ID = ResourceLocation.m_214293_((String)"certain_questing_additions", (String)"custom_background");

    private ModShaders() {
    }

    public static void register(ResourceLocation id, ShaderInstance program) {
        if (id == null || program == null) {
            return;
        }
        PROGRAMS.put(id, program);
    }

    public static ShaderInstance get(ResourceLocation id) {
        if (id == null) {
            return PROGRAMS.get(DEFAULT_BACKGROUND_ID);
        }
        ShaderInstance shader = PROGRAMS.get(id);
        if (shader != null) {
            return shader;
        }
        return PROGRAMS.get(DEFAULT_BACKGROUND_ID);
    }

    public static boolean contains(ResourceLocation id) {
        return PROGRAMS.containsKey(id);
    }

    public static Collection<ResourceLocation> registeredIds() {
        return PROGRAMS.keySet();
    }
}

